* { box-sizing: border-box; }
body { margin: 0; background: #f4f6fa; color: #202938; font: 16px/1.5 system-ui, sans-serif; }
.shell { width: min(680px, calc(100% - 32px)); margin: 64px auto; padding: 32px; background: white; border: 1px solid #e1e6ee; border-radius: 12px; box-shadow: 0 8px 28px #17243a0c; }
h1 { margin: 0 0 24px; font-size: 30px; }
form { display: flex; align-items: center; flex-wrap: wrap; gap: 12px; }
label { font-weight: 600; }
input { min-width: 180px; flex: 1; padding: 10px 12px; border: 1px solid #aeb9c9; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #315fc4; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #234da8; }
button:focus-visible, input:focus-visible { outline: 3px solid #9db9ff; outline-offset: 2px; }
[role="alert"] { color: #b42318; margin: 12px 0; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 12px; padding: 14px 16px; border: 1px solid #e1e6ee; border-radius: 8px; }
.project-row span { overflow-wrap: anywhere; }

